// Repair legacy UTF-8 text that was accidentally saved as Windows-1252 characters.
const legacyCp1252 = new Map([["€",0x80],["‚",0x82],["ƒ",0x83],["„",0x84],["…",0x85],["†",0x86],["‡",0x87],["ˆ",0x88],["‰",0x89],["Š",0x8a],["‹",0x8b],["Œ",0x8c],["Ž",0x8e],["‘",0x91],["’",0x92],["“",0x93],["”",0x94],["•",0x95],["–",0x96],["—",0x97],["˜",0x98],["™",0x99],["š",0x9a],["›",0x9b],["œ",0x9c],["ž",0x9e],["Ÿ",0x9f]]);
function normalizeLegacy(value) {
  if (typeof value !== "string" || !/[ØÙÃÂ]/.test(value)) return value;
  const bytes = Uint8Array.from([...value].map((char) => legacyCp1252.get(char) ?? (char.charCodeAt(0) & 0xff)));
  return new TextDecoder().decode(bytes);
}
function normalizeTree(value) {
  if (typeof value === "string") return normalizeLegacy(value);
  if (Array.isArray(value)) return value.map(normalizeTree);
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalizeTree(item)]));
  return value;
}
for (const locale of locales) tr[locale] = normalizeTree(tr[locale]);
for (let index = 0; index < guides.length; index += 1) guides[index] = normalizeTree(guides[index]);
const descriptionTail = {
  ar: " راجع الفئات والمصادر قبل الاختيار.",
  en: " Review trim details and sources before choosing.",
  fr: " Vérifiez finitions et sources avant de choisir.",
  pt: " Confira versões e fontes antes de escolher.",
};
for (const guide of guides) for (const locale of locales) {
  let value = guide.copy[locale].description.trim();
  while (value.length < 120) value += descriptionTail[locale];
  if (value.length > 160) {
    value = value.slice(0, 160);
    const lastSpace = value.lastIndexOf(" ");
    if (lastSpace >= 120) value = value.slice(0, lastSpace).trimEnd();
  }
  guide.copy[locale].description = value;
}

const escape = (value) => String(value).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
const titleFor = (guide, lang) => guide.copy[lang].title;
function articlePage(guide, lang) {
  const c=tr[lang], text=guide.copy[lang], canonical=BASE+guide.slug+(lang==="ar"?"":"-"+lang)+".html";
  if(text.description.length<120 || text.description.length>160) throw new Error(`${guide.slug}/${lang}: description length ${text.description.length}`);
  const alternates=locales.map(l=>`<link rel="alternate" hreflang="${l}" href="${BASE+guide.slug+(l==="ar"?"":"-"+l)+".html"}">`).join("\n");
  if (!guide.models || !text.rows || text.rows.length > guide.models.length) throw new Error(`${guide.slug}/${lang}: comparison rows (${text.rows?.length ?? 0}) exceed source links (${guide.models?.length ?? 0})`);
  const rows=text.rows.map((row,i)=>`<tr><th scope="row"><a href="${guide.models[i].url}" target="_blank" rel="noopener noreferrer">${escape(row[0])}</a></th><td>${escape(row[1])}</td><td>${escape(row[2])}</td></tr>`).join("");
  const chart=guide.chart[lang], max=Math.max(...chart.values), rtl=lang==="ar";
  const bars=chart.values.map((value,i)=>{const y=44+i*92,w=Math.round(830*value/max);return `<text x="${rtl?880:20}" y="${y}" text-anchor="${rtl?"end":"start"}" direction="${rtl?"rtl":"ltr"}">${escape(chart.labels[i])}</text><rect x="20" y="${y+12}" width="${w}" height="28" rx="6" fill="${["#2684d8","#ed9a32","#45a786","#7756b8"][i%4]}"/><text x="${Math.min(875,28+w)}" y="${y+32}">${value}</text>`}).join("");
  const related=guides.filter(other=>other!==guide).slice(0,3).map(other=>`<li><a href="${other.slug+(lang==="ar"?"":"-"+lang)+".html"}">${escape(titleFor(other,lang))}</a></li>`).join("");
  const sources=guide.models.map(model=>`<li><a href="${model.url}" target="_blank" rel="noopener noreferrer">${escape(model.name)} — ${escape(c.official)}</a><small>${escape(c.siteScope)}</small></li>`).join("");
  const description=escape(text.description), title=escape(text.title+" | AutoAtlas");
  const localeTag={ar:"ar_AR",en:"en_US",fr:"fr_FR",pt:"pt_BR"}[lang];
  const pageSlug=guide.slug+(lang==="ar"?"":"-"+lang)+".html";
  return `<!doctype html><html lang="${lang}"${lang==="ar"?' dir="rtl"':''}><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#2563eb"><meta name="robots" content="index, follow"><title>${title}</title><meta name="description" content="${description}"><link rel="canonical" href="${canonical}">${alternates}<link rel="alternate" hreflang="x-default" href="${BASE+guide.slug+".html"}"><link rel="stylesheet" href="style.css"><script defer src="script.js"></script><meta property="og:type" content="article"><meta property="og:site_name" content="AutoAtlas"><meta property="og:locale" content="${localeTag}"><meta property="og:title" content="${title}"><meta property="og:description" content="${description}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="https://images.unsplash.com/photo-1494976388531-d1058494cdd8?fit=crop&amp;fm=jpg&amp;h=630&amp;w=1200&amp;q=80"><meta property="og:image:alt" content="${escape(text.title)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${title}"><meta name="twitter:description" content="${description}"><meta name="twitter:image" content="https://images.unsplash.com/photo-1494976388531-d1058494cdd8?fit=crop&amp;fm=jpg&amp;h=630&amp;w=1200&amp;q=80"></head><body><header class="site-header"><div class="container"><div class="nav-container"><a class="brand" href="${lang==="ar"?"index.html":lang+".html"}"><span class="brand-mark">A</span><span>AutoAtlas</span></a><nav class="main-nav" aria-label="${escape(c.articles)}"><a href="${files[lang]}">${escape(c.articles)}</a><a href="${lang==="ar"?"technology.html":"technology-"+lang+".html"}">${lang==="ar"?"التقنيات":lang==="fr"?"Technologie":lang==="pt"?"Tecnologia":"Technology"}</a></nav><div class="lang-switch">${locales.map(l=>`<a${l===lang?' class="active"':''} href="${guide.slug+(l==="ar"?"":"-"+l)+".html"}">${{ar:"العربية",en:"English",fr:"Français",pt:"Português"}[l]}</a>`).join("")}</div></div></div></header><main class="container page-main buying-guide-page"><nav class="technology-breadcrumb" aria-label="${escape(c.articles)}"><a href="${files[lang]}">${escape(c.articles)}</a><span aria-hidden="true">/</span><span>${escape(c.label)}</span></nav><section class="technology-detail-hero"><span class="technology-category-icon" aria-hidden="true">🚘</span><span class="section-kicker">${escape(c.category)}</span><h1>${escape(text.title)}</h1><p>${escape(text.intro)}</p></section><aside class="author-authority-card"><div class="author-byline"><span class="author-monogram" aria-hidden="true">MA</span><div><span class="technology-card-index">${escape(c.review)}</span><p><a href="${lang==="ar"?"author.html":"author-"+lang+".html"}">Mu'minah Alimat</a></p></div></div><dl class="author-review-metadata"><div><dt>${escape(c.last)}</dt><dd>${escape(c.notRecorded)}</dd></div><div><dt>${escape(c.status)}</dt><dd>${escape(c.pending)}</dd></div><div><dt>${escape(c.sources)}</dt><dd>${guide.models.length} ${lang==="ar"?"روابط مصنعين":lang==="fr"?"liens constructeurs":lang==="pt"?"links de fabricantes":"manufacturer links"}</dd></div></dl></aside><p class="buying-guide-lead">${escape(c.lead)}</p><aside class="did-you-know"><strong>${escape(c.fact)}</strong><p>${escape(c.factText)}</p></aside><section class="buying-guide-chart"><h2>${escape(c.chart)}: ${escape(chart.title)}</h2><figure><svg lang="${lang}" viewBox="0 0 900 ${Math.max(310,chart.values.length*92+70)}" role="img" aria-labelledby="${guide.slug}-${lang}-chart-title ${guide.slug}-${lang}-chart-desc"><title id="${guide.slug}-${lang}-chart-title">${escape(chart.title)}</title><desc id="${guide.slug}-${lang}-chart-desc">${escape(c.chartAlt)} ${escape(chart.labels.join(", "))}: ${chart.values.join(", ")} ${escape(chart.unit)}.</desc><text x="18" y="30" font-size="16" font-weight="700">${escape(chart.unit)}</text>${bars}</svg><figcaption>${escape(text.take)}</figcaption></figure></section><section class="buying-guide-table"><h2>${escape(c.table)}</h2><div class="technology-table-wrap"><table><thead><tr><th>${escape(c.model)}</th><th>${escape(c.metric)}</th><th>${escape(c.fit)}</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="buying-guide-method"><h2>${escape(c.method)}</h2><p>${escape(text.take)}</p><p>${escape(c.methodText)}</p></section><section class="buying-guide-checklist"><h2>${escape(c.check)}</h2><div class="buying-guide-card-grid">${c.cards.map((item,i)=>`<article class="content-card"><span aria-hidden="true">${["①","②","③"][i]}</span><p>${escape(item)}</p></article>`).join("")}</div></section><section class="sources-box"><h2>${escape(c.sources)}</h2><ol>${sources}</ol><p>${escape(c.siteScope)}</p></section><nav class="technology-related" aria-label="${escape(c.related)}"><h2>${escape(c.related)}</h2><ul>${related}</ul><a href="${files[lang]}">${escape(c.back)}</a></nav></main><footer class="site-footer"><div class="container"><p>${escape(c.label)} · AutoAtlas</p><p><a href="${lang==="ar"?"contact.html":"contact-"+lang+".html"}">${lang==="ar"?"تواصل":lang==="fr"?"Contact":lang==="pt"?"Contato":"Contact"}</a></p></div></footer></body></html>`;
}

for (const guide of guides) for (const lang of locales) writeFileSync(join(ROOT,guide.slug+(lang==="ar"?"":"-"+lang)+".html"),articlePage(guide,lang),"utf8");

// Expose the six guides as crawlable links on each localized articles index.
for (const lang of locales) {
  const path=join(ROOT,files[lang]); let html=readFileSync(path,"utf8");
  const marker="<!-- AUTO-GENERATED:2026-BUYING-GUIDES:START -->";
  const end="<!-- AUTO-GENERATED:2026-BUYING-GUIDES:END -->";
  const cards=guides.map((guide,i)=>`<a class="content-card buying-guide-index-card" href="${guide.slug+(lang==="ar"?"":"-"+lang)+".html"}"><span class="section-kicker">${escape(tr[lang].label)} 0${i+1}</span><h3>${escape(guide.copy[lang].title)}</h3><p>${escape(guide.copy[lang].intro)}</p><span>${lang==="ar"?"اقرأ الدليل ←":lang==="fr"?"Lire le guide →":lang==="pt"?"Ler o guia →":"Read guide →"}</span></a>`).join("");
  const section=`${marker}<section class="buying-guide-index" aria-labelledby="buying-guide-index-title"><span class="section-kicker">${escape(tr[lang].label)}</span><h2 id="buying-guide-index-title">${escape(tr[lang].related)}</h2><div class="buying-guide-card-grid">${cards}</div></section>${end}`;
  const re=new RegExp(`${marker}[\\s\\S]*?${end}`);
  if(re.test(html)) html=html.replace(re,section); else {const at=html.indexOf('<div class="articles-list">');if(at<0)throw new Error(`${files[lang]}: article list insertion point missing`);html=html.slice(0,at)+section+"\n"+html.slice(at);}
  writeFileSync(path,html,"utf8");
}

// Add all 24 language URLs once. Their HTML carries reciprocal hreflang links.
const sitemapPath=join(ROOT,"sitemap.xml"); let sitemap=readFileSync(sitemapPath,"utf8");
for(const guide of guides) for(const lang of locales){const page=guide.slug+(lang==="ar"?"":"-"+lang)+".html",loc=BASE+page;if(sitemap.includes(`<loc>${loc}</loc>`))continue;const entry=`  <url>\n    <loc>${loc}</loc>\n    <changefreq>monthly</changefreq>\n    <priority>0.7</priority>\n  </url>\n`;sitemap=sitemap.replace(/<\/urlset>/i,`${entry}</urlset>`);}
writeFileSync(sitemapPath,sitemap,"utf8");
console.log(`Generated ${guides.length*locales.length} localized 2026 buying guides and added them to article indexes and sitemap.`);
